1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 台账文件已存在但没有任何内容（零字节，无论原本就是空文件还是使用中被截断）
31	// 时按损坏处理；已有台账文件无法读取、解析，存在两条配方编号与版本号
32	// 完全相同的配方记录，任一配方版本的任一物料每份克数不是正数，
33	// 任一配方版本内同一物料编号出现多次，
34	// 任一批次绑定的配方版本未登记，
35	// 已保存投料的物料编号不属于该批次绑定的配方版本，
36	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
37	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
38	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
39	func Open(dir string) (*Store, error) {
40		if dir == "" {
41			return nil, errors.New("数据位置不能为空")
42		}
43		if err := os.MkdirAll(dir, 0o755); err != nil {
44			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
45		}
46		info, err := os.Stat(dir)
47		if err != nil {
48			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
49		}
50		if !info.IsDir() {
51			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
52		}
53	
54		lockPath := filepath.Join(dir, lockFileName)
55		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
56		if err != nil {
57			return nil, fmt.Errorf("打开锁文件失败: %w", err)
58		}
59	
60		s := &Store{dir: dir, lockFile: lf}
61		if err := s.load(); err != nil {
62			lf.Close()
63			return nil, err
64		}
65		return s, nil
66	}
67	
68	// Close 释放台账占用的文件锁。
69	func (s *Store) Close() error {
70		s.mu.Lock()
71		defer s.mu.Unlock()
72		if s.lockFile == nil {
73			return nil
74		}
75		err := s.lockFile.Close()
76		s.lockFile = nil
77		return err
78	}
79	
80	func (s *Store) lockExclusive() error {
81		if s.lockFile == nil {
82			return errors.New("台账已关闭")
83		}
84		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
85			return fmt.Errorf("锁定台账失败: %w", err)
86		}
87		return nil
88	}
89	
90	func (s *Store) lockShared() error {
91		if s.lockFile == nil {
92			return errors.New("台账已关闭")
93		}
94		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
95			return fmt.Errorf("锁定台账失败: %w", err)
96		}
97		return nil
98	}
99	
100	func (s *Store) unlock() {
101		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
102	}
103	
104	func (s *Store) load() error {
105		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
106		if err != nil {
107			if os.IsNotExist(err) {
108				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
109				return nil
110			}
111			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
112		}
113		if len(data) == 0 {
114			// 区分“没有台账文件”与“已有文件但内容为空”：文件不存在才算首次使用，
115			// 零字节文件（原本就为空或使用中被截断）一律按损坏处理——既不能当成
116			// 空台账补写，也不能凭内存中的旧记录还原，调用方必须明确知道无法读取。
117			return fmt.Errorf("%w: 台账文件 %q 没有内容", ErrCorruptData, filepath.Join(s.dir, stateFileName))
118		}
119		var st persistedState
120		if err := json.Unmarshal(data, &st); err != nil {
121			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
122		}
123		if st.Version != stateVersion {
124			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
125		}
126		if err := validateState(&st); err != nil {
127			return err
128		}
129		if st.Requests == nil {
130			st.Requests = map[string]*requestRecord{}
131		}
132		s.state = &st
133		return nil
134	}
135	
136	// validateState 检查台账的引用完整性与数量合法性：
137	//   - 配方由配方编号与版本号共同识别，同一台账内每组编号+版本号只能
138	//     对应一条配方记录。只要同组出现第二条记录，无论名称、物料、每份克数
139	//     是否相同（即使内容完全一致），整份台账即视为损坏：不能挑第一条或
140	//     最后一条、不能合并物料、也不能自行删除一条后继续——重复记录会让
141	//     查询结果与批次的应投依据取决于文件中的排列顺序。重复版本即使尚未
142	//     被任何批次引用也一样拒绝，其他配方与批次完整也不能放行本次读取。
143	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
144	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
145	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
146	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
147	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
148	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
149	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
150	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
151	//     不同版本、不同配方各自使用同一物料编号不受影响。
152	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
153	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
154	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
155	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
156	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
157	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
158	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
159	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
160	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
161	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
162	func validateState(st *persistedState) error {
163		// 先按“配方编号 + 版本号”唯一标识遍历全部配方记录：同组出现第二条
164		// 记录即数据损坏，必须先于一切按标识查找的校验拒绝——否则重复记录
165		// 会让 findRecipe 总是返回排在前面的一条，查询结果与批次应投依据都
166		// 取决于文件排列顺序。完全相同的内容也不是合法重复。
167		versions := make(map[recipeKey]bool, len(st.Recipes))
168		for _, r := range st.Recipes {
169			if r == nil {
170				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
171			}
172			key := recipeKey{r.RecipeNo, r.Version}
173			if versions[key] {
174				return fmt.Errorf("%w: 配方编号 %q 版本号 %q 的配方记录重复",
175					ErrCorruptData, r.RecipeNo, r.Version)
176			}
177			versions[key] = true
178		}
179		for _, r := range st.Recipes {
180			seen := make(map[string]bool, len(r.Materials))
181			for _, m := range r.Materials {
182				if seen[m.MaterialNo] {
183					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
184						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
185				}
186				seen[m.MaterialNo] = true
187				if m.GramsMilli <= 0 {
188					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
189						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
190				}
191			}
192		}
193		for _, b := range st.Batches {
194			if b == nil {
195				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
196			}
197			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
198			if r == nil {
199				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
200					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
201			}
202			if err := validateFeedings(b, r); err != nil {
203				return err
204			}
205		}
206		return nil
207	}
208	
209	// validateFeedings 检查一个批次内已保存投料的合法性与配方归属。
210	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
211	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
212	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
213	// 在此拒绝。
214	func validateFeedings(b *batchRecord, r *recipeRecord) error {
215		acc := newFeedingAccumulator()
216		for _, f := range b.Feedings {
217			belongs := false
218			for _, m := range r.Materials {
219				if m.MaterialNo == f.MaterialNo {
220					belongs = true
221					break
222				}
223			}
224			if !belongs {
225				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
226					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
227			}
228			if f.GramsMilli <= 0 {
229				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
230					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
231			}
232			if !acc.add(f.MaterialNo, f.GramsMilli) {
233				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
234					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
235			}
236		}
237		return nil
238	}
239	
240	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
241	func (s *Store) persist(st *persistedState) error {
242		data, err := json.MarshalIndent(st, "", "  ")
243		if err != nil {
244			return err
245		}
246		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
247		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
248		if err != nil {
249			return err
250		}
251		if _, err := f.Write(data); err != nil {
252			f.Close()
253			return err
254		}
255		if err := f.Sync(); err != nil {
256			f.Close()
257			return err
258		}
259		if err := f.Close(); err != nil {
260			return err
261		}
262		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
263			return err
264		}
265		if d, err := os.Open(s.dir); err == nil {
266			_ = d.Sync()
267			_ = d.Close()
268		}
269		return nil
270	}
271	
272	func cloneState(st *persistedState) (*persistedState, error) {
273		data, err := json.Marshal(st)
274		if err != nil {
275			return nil, err
276		}
277		var out persistedState
278		if err := json.Unmarshal(data, &out); err != nil {
279			return nil, err
280		}
281		if out.Requests == nil {
282			out.Requests = map[string]*requestRecord{}
283		}
284		return &out, nil
285	}
286	
287	// write 是所有写入操作的统一入口：
288	//   - reqNo 为空直接报错；
289	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
290	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
291	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
292	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
293	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
294		if reqNo == "" {
295			return errors.New("请求编号不能为空")
296		}
297		s.mu.Lock()
298		defer s.mu.Unlock()
299		if err := s.lockExclusive(); err != nil {
300			return err
301		}
302		defer s.unlock()
303	
304		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
305		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
306		if err := s.load(); err != nil {
307			return err
308		}
309	
310		payloadRaw, err := json.Marshal(payload)
311		if err != nil {
312			return err
313		}
314		payloadStr := string(payloadRaw)
315	
316		if req, ok := s.state.Requests[reqNo]; ok {
317			if req.Op != op || req.Payload != payloadStr {
318				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
319					ErrRequestConflict, reqNo, req.Op, op)
320			}
321			if err := json.Unmarshal(req.Result, out); err != nil {
322				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
323			}
324			return nil
325		}
326	
327		clone, err := cloneState(s.state)
328		if err != nil {
329			return err
330		}
331		result, err := apply(clone)
332		if err != nil {
333			return err
334		}
335		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
336		if err := s.persist(clone); err != nil {
337			return fmt.Errorf("保存台账失败: %w", err)
338		}
339		s.state = clone
340		if err := json.Unmarshal(result, out); err != nil {
341			return fmt.Errorf("解析请求结果失败: %w", err)
342		}
343		return nil
344	}
345	
346	// read 在共享锁下读取当前状态。
347	func (s *Store) read(fn func(*persistedState) error) error {
348		s.mu.Lock()
349		defer s.mu.Unlock()
350		if err := s.lockShared(); err != nil {
351			return err
352		}
353		defer s.unlock()
354		if err := s.load(); err != nil {
355			return err
356		}
357		return fn(s.state)
358	}
359	
360	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
361	
362	func buildRecipeView(r *recipeRecord) *RecipeView {
363		mats := make([]MaterialView, 0, len(r.Materials))
364		for _, m := range r.Materials {
365			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
366		}
367		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
368	}
369	
370	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
371		v := &BatchView{
372			BatchNo:         b.BatchNo,
373			RecipeNo:        r.RecipeNo,
374			RecipeVersion:   r.Version,
375			RecipeName:      r.Name,
376			PlannedPortions: b.PlannedPortions,
377			Status:          b.Status,
378			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
379			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
380		}
381	
382		for _, f := range b.Feedings {
383			v.Feedings = append(v.Feedings, FeedingView{
384				Seq:        f.Seq,
385				MaterialNo: f.MaterialNo,
386				Grams:      f.GramsMilli.String(),
387				Time:       f.Time,
388				Registrar:  f.Registrar,
389			})
390		}
391	
392		// 按物料累计实投量；台账在读取时已通过 validateFeedings 校验，
393		// 这里仍用同一套累计规则防一手整数回绕。
394		acc := newFeedingAccumulator()
395		for _, f := range b.Feedings {
396			if !acc.add(f.MaterialNo, f.GramsMilli) {
397				return nil, fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出可表示范围",
398					ErrCorruptData, b.BatchNo, f.MaterialNo)
399			}
400		}
401	
402		// 数量核对按配方物料逐项列出；台账在读取时已通过 validateState 校验，
403		// 这里仍防一手同一版本内物料编号重复，避免返回重复的数量核对项。
404		seen := make(map[string]bool, len(r.Materials))
405		for _, m := range r.Materials {
406			if seen[m.MaterialNo] {
407				return nil, fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
408					ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
409			}
410			seen[m.MaterialNo] = true
411			required, err := multiplyPortions(m.GramsMilli, b.PlannedPortions)
412			if err != nil {
413				return nil, fmt.Errorf("批次 %q 数量核对失败: %w", b.BatchNo, err)
414			}
415			act := acc.total(m.MaterialNo)
416			v.Materials = append(v.Materials, MaterialRequirement{
417				MaterialNo:      m.MaterialNo,
418				RequiredGrams:   required.String(),
419				ActualGrams:     act.String(),
420				DifferenceGrams: (act - required).String(),
421			})
422		}
423		return v, nil
424	}
425	
426	// recipeKey 是配方的唯一标识：配方编号与版本号的组合，采用精确匹配。
427	type recipeKey struct {
428		recipeNo string
429		version  string
430	}
431	
432	func findRecipe(st *persistedState, recipeNo, version string) *recipeRecord {
433		for _, r := range st.Recipes {
434			if r.RecipeNo == recipeNo && r.Version == version {
435				return r
436			}
437		}
438		return nil
439	}
440	
441	func findBatch(st *persistedState, batchNo string) *batchRecord {
442		for _, b := range st.Batches {
443			if b.BatchNo == batchNo {
444				return b
445			}
446		}
447		return nil
448	}
