214	// AddFeeding 向执行中的批次追加一次投料。
215	// 投料包含物料编号、克数（正数、最多三位小数）、投料时间和登记人；
216	// 物料必须属于该批次绑定的配方版本。允许实际投料不足或超过应投量；
217	// 已登记的投料不能修改或删除，关闭后也不能追加。
218	// 同一批次内每种物料的累计实投量（仅按该物料统计）上限为
219	// 9223372036854775.807 克，本次投料后恰好等于上限仍允许，超过则返回
220	// ErrInvalidInput 且不保存本次投料。
221	// 投料按成功登记的先后顺序编号，不按投料时间重排。
222	func (s *Store) AddFeeding(reqNo, batchNo, materialNo, grams string, t time.Time, registrar string) (*FeedingView, error) {
223		payload := addFeedingPayload{
224			BatchNo:    batchNo,
225			MaterialNo: materialNo,
226			Grams:      grams,
227			Time:       t,
228			Registrar:  registrar,
229		}
230		var out FeedingView
231		err := s.write(reqNo, opAddFeeding, payload, func(st *persistedState) (json.RawMessage, error) {
232			if materialNo == "" {
233				return nil, fmt.Errorf("%w: 物料编号不能为空", ErrInvalidInput)
234			}
235			if registrar == "" {
236				return nil, fmt.Errorf("%w: 登记人不能为空", ErrInvalidInput)
237			}
238			milli, err := parseGrams(grams)
239			if err != nil {
240				return nil, fmt.Errorf("%w: 物料 %q 的克数: %v", ErrInvalidInput, materialNo, err)
241			}
242			b := findBatch(st, batchNo)
243			if b == nil {
244				return nil, fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
245			}
246			if b.Status != StatusExecuting {
247				return nil, fmt.Errorf("%w: 批次 %q 状态为 %s，只有执行中的批次可以投料", ErrInvalidState, batchNo, b.Status)
248			}
249			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
250			if r == nil {
251				return nil, fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
252					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
253			}
254			belongs := false
255			for _, m := range r.Materials {
256				if m.MaterialNo == materialNo {
257					belongs = true
258					break
259				}
260			}
261			if !belongs {
262				return nil, fmt.Errorf("%w: 物料 %q 不在配方 %q 版本 %q 中",
263					ErrMaterialNotInRecipe, materialNo, r.RecipeNo, r.Version)
264			}
265	
266			// 上限按物料分别判断：只累计该物料已登记的投料，
267			// 其他物料的投料量不参与，也不互相抵消。
268			acc := newFeedingAccumulator()
269			fit := true
270			for _, f := range b.Feedings {
271				if !acc.add(f.MaterialNo, f.GramsMilli) {
272					fit = false
273					break
274				}
275			}
276			if !fit || !acc.add(materialNo, milli) {
277				return nil, fmt.Errorf("%w: 物料 %q 的数量超出范围：本次投料后累计实投将超过上限 %s 克",
278					ErrInvalidInput, materialNo, maxGramsMilli)
279			}
280	
281			seq := len(b.Feedings) + 1
282			rec := feedingRecord{
283				Seq:        seq,
284				MaterialNo: materialNo,
285				GramsMilli: milli,
286				Time:       t,
287				Registrar:  registrar,
288			}
289			view := FeedingView{
290				Seq:        seq,
291				MaterialNo: materialNo,
292				Grams:      milli.String(),
293				Time:       t,
294				Registrar:  registrar,
295			}
296			raw, err := json.Marshal(view)
297			if err != nil {
298				return nil, err
299			}
300			b.Feedings = append(b.Feedings, rec)
301			return raw, nil
302		}, &out)
303		if err != nil {
304			return nil, err
305		}
306		return &out, nil
307	}
308	
309	// GetBatch 按批次编号查询，返回未找到（ErrNotFound）时表示批次不存在。
310	// 返回内容包含所用配方版本、计划份数、状态、全部投料（登记顺序），
311	// 以及按物料逐项的应投量、累计实投量和差额；无投料的物料也会列出。
312	// 返回的视图是台账数据的副本，调用方修改不会影响台账。
313	func (s *Store) GetBatch(batchNo string) (*BatchView, error) {
314		var out *BatchView
315		err := s.read(func(st *persistedState) error {
316			b := findBatch(st, batchNo)
317			if b == nil {
318				return fmt.Errorf("%w: 批次 %q", ErrNotFound, batchNo)
319			}
320			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
321			if r == nil {
322				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 不存在",
323					ErrCorruptData, batchNo, b.RecipeNo, b.RecipeVersion)
324			}
325			view, err := buildBatchView(b, r)
326			if err != nil {
327				return err
328			}
329			out = view
330			return nil
331		})
332		if err != nil {
333			return nil, err
334		}
335		return out, nil
336	}
