1	package release
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	// 构造两条具有相同配方编号与版本号的配方记录；
15	// identical 为 true 时两条内容（名称、物料、每份克数）完全一致。
16	func recipeVersionDupRecords(identical bool) []*recipeRecord {
17		first := &recipeRecord{RecipeNo: "R2", Version: "v1", Name: "配方二",
18			Materials: []materialRecord{{MaterialNo: "M1", GramsMilli: 100000}}}
19		var second *recipeRecord
20		if identical {
21			second = &recipeRecord{RecipeNo: "R2", Version: "v1", Name: "配方二",
22				Materials: []materialRecord{{MaterialNo: "M1", GramsMilli: 100000}}}
23		} else {
24			second = &recipeRecord{RecipeNo: "R2", Version: "v1", Name: "配方二改名",
25				Materials: []materialRecord{{MaterialNo: "M2", GramsMilli: 200000}}}
26		}
27		return []*recipeRecord{first, second}
28	}
29	
30	// Open 时只要存在两条配方编号与版本号完全相同的配方记录就必须返回
31	// ErrCorruptData：内容不同、内容完全一致、重复版本未被任何批次选用，
32	// 三种情形都拒绝；错误信息需包含重复的配方编号与版本号；
33	// 不返回可用的台账对象，也不改写原文件；不得挑第一条或最后一条放行。
34	func TestOpenRejectsDuplicateRecipeVersion(t *testing.T) {
35		cases := []struct {
36			name      string
37			identical bool
38			withUse   bool // 是否有批次绑定重复版本
39		}{
40			{"名称物料不同且有批次绑定", false, true},
41			{"两条记录内容完全一致", true, true},
42			{"重复版本未被任何批次选用", false, false},
43		}
44		for _, tc := range cases {
45			t.Run(tc.name, func(t *testing.T) {
46				dir := t.TempDir()
47				st := &persistedState{
48					Version: stateVersion,
49					Recipes: append([]*recipeRecord{recipeR1v1()}, recipeVersionDupRecords(tc.identical)...),
50				}
51				if tc.withUse {
52					st.Batches = []*batchRecord{{
53						BatchNo: "B1", RecipeNo: "R2", RecipeVersion: "v1",
54						PlannedPortions: 2, Status: StatusExecuting,
55					}}
56				}
57				original := writeStateFile(t, dir, st)
58	
59				s, err := Open(dir)
60				if !errors.Is(err, ErrCorruptData) {
61					t.Fatalf("重复配方版本应返回 ErrCorruptData，得到 %v", err)
62				}
63				if s != nil {
64					s.Close()
65					t.Fatalf("损坏台账不应返回可用的 Store 对象")
66				}
67				msg := err.Error()
68				for _, want := range []string{"R2", "v1"} {
69					if !strings.Contains(msg, want) {
70						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
71					}
72				}
73				// 原台账内容保留：不得挑一条、合并物料或自行删除一条后另存。
74				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
75				if err != nil {
76					t.Fatal(err)
77				}
78				if !bytes.Equal(got, original) {
79					t.Fatalf("拒绝打开不应改动台账文件")
80				}
81			})
82		}
83	}
84	
85	// 台账里其他配方与批次都完整也不能绕过：只要一组编号+版本号出现两条，
86	// Open 整体失败，即使重复版本本身未被任何批次引用。
87	func TestOpenDuplicateRecipeVersionAmongCompleteRecords(t *testing.T) {
88		dir := t.TempDir()
89		writeStateFile(t, dir, &persistedState{
90			Version: stateVersion,
91			Recipes: append(
92				[]*recipeRecord{recipeR1v1()},
93				recipeVersionDupRecords(false)...,
94			),
95			Batches: []*batchRecord{
96				{BatchNo: "B-ok", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 1, Status: StatusClosed},
97			},
98		})
99		if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
100			t.Fatalf("存在完整配方与批次也应整体拒绝，得到 %v", err)
101		}
102	}
103	
104	// 台账打开后本地文件被改坏（多出一条相同编号+版本号的配方记录）：
105	// 下一次查询或写入都必须返回 ErrCorruptData，即使查询的是另一个正常版本、
106	// 修改的是另一个正常批次；不得凭此前读取过的内容返回旧结果；
107	// 被拒绝的写入不留业务记录、不占用请求编号；恢复后原记录继续可用。
108	func TestDuplicateRecipeVersionAfterOpenDetectedOnNextAccess(t *testing.T) {
109		dir := t.TempDir()
110		s, err := Open(dir)
111		if err != nil {
112			t.Fatal(err)
113		}
114		defer s.Close()
115	
116		if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
117			{MaterialNo: "M1", Grams: "100"},
118		}); err != nil {
119			t.Fatal(err)
120		}
121		if _, err := s.RegisterRecipe("r2", "R2", "v1", "配方二", []MaterialInput{
122			{MaterialNo: "M1", Grams: "5"},
123		}); err != nil {
124			t.Fatal(err)
125		}
126		// B1 绑定正常版本 R1/v1；重复将发生在未被批次引用的 R2/v1 上。
127		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 2); err != nil {
128			t.Fatal(err)
129		}
130		if _, err := s.StartBatch("s1", "B1"); err != nil {
131			t.Fatal(err)
132		}
133		fixedTime := time.Date(2026, 8, 1, 9, 0, 0, 0, time.UTC)
134		if _, err := s.AddFeeding("feed-1", "B1", "M1", "50", fixedTime, "张三"); err != nil {
135			t.Fatal(err)
136		}
137	
138		// 保存完好时的文件内容，随后追加一条 R2/v1 记录（编号+版本号重复）。
139		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
140		if err != nil {
141			t.Fatal(err)
142		}
143		var broken persistedState
144		if err := json.Unmarshal(good, &broken); err != nil {
145			t.Fatal(err)
146		}
147		broken.Recipes = append(broken.Recipes, &recipeRecord{
148			RecipeNo: "R2", Version: "v1", Name: "配方二改名",
149			Materials: []materialRecord{{MaterialNo: "M9", GramsMilli: 7000}},
150		})
151		badBytes := writeStateFile(t, dir, &broken)
152	
153		// 查询：重复版本、正常版本，以及绑定正常版本的批次，全部失败；
154		// 不能凭此前读取过的内容返回旧结果。
155		if _, err := s.GetRecipe("R2", "v1"); !errors.Is(err, ErrCorruptData) {
156			t.Fatalf("文件损坏后查询重复版本应返回 ErrCorruptData，得到 %v", err)
157		}
158		if _, err := s.GetRecipe("R1", "v1"); !errors.Is(err, ErrCorruptData) {
159			t.Fatalf("即使查询另一个正常版本也必须拒绝，得到 %v", err)
160		}
161		if _, err := s.GetBatch("B1"); !errors.Is(err, ErrCorruptData) {
