36				{RecipeNo: "R2", Version: "v1", Name: "配方二", Materials: []materialRecord{
37					{MaterialNo: "M3", GramsMilli: 300000},
38				}},
39			},
40			Batches: []*batchRecord{{
41				BatchNo:         "B-bad",
42				RecipeNo:        "R1",
43				RecipeVersion:   "v1",
44				PlannedPortions: 2,
45				Status:          status,
46				Feedings: []feedingRecord{
47					{Seq: 1, MaterialNo: "M1", GramsMilli: 100000, Time: time.Now(), Registrar: "张三"},
48					{Seq: 2, MaterialNo: problemMaterial, GramsMilli: 50000, Time: time.Now(), Registrar: "李四"},
49				},
50			}},
51		})
52	}
53	
54	// Open 读取已有台账时，已保存投料的物料不属于批次绑定版本必须返回
55	// ErrCorruptData：物料完全不存在、只出现在同编号其他版本、只出现在另一
56	// 配方中都不能作为合法依据；问题投料克数为正、累计不超限也不能放行。
57	// 错误信息必须指出批次编号、登记序号、问题物料编号以及绑定的配方编号
58	// 与版本号；不得返回可用的 Store，也不得改写原文件。
59	func TestOpenRejectsFeedingMaterialOutsideBoundVersion(t *testing.T) {
60		materialCases := []struct {
61			name string
62			mat  string
63		}{
64			{"物料在台账中完全不存在", "M9"},
65			{"物料只出现在同编号另一版本 R1/v2", "M2"},
66			{"物料只出现在另一配方 R2/v1", "M3"},
67		}
68		// 已关闭批次不再追加投料，但其历史投料同样受归属规则约束，不能跳过。
69		for _, status := range []BatchStatus{StatusExecuting, StatusClosed} {
70			for _, tc := range materialCases {
71				t.Run(string(status)+"/"+tc.name, func(t *testing.T) {
72					dir := t.TempDir()
73					original := writeMembershipFeedingState(t, dir, tc.mat, status)
74	
75					s, err := Open(dir)
76					if !errors.Is(err, ErrCorruptData) {
77						t.Fatalf("投料物料不属于绑定版本应返回 ErrCorruptData，得到 %v", err)
78					}
79					if s != nil {
80						s.Close()
81						t.Fatalf("损坏台账不应返回可继续使用的 Store 对象")
82					}
83					msg := err.Error()
84					for _, want := range []string{"B-bad", "第 2 条", tc.mat, "R1", "v1", "不属于"} {
85						if !strings.Contains(msg, want) {
86							t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
87						}
88					}
89					// 读取失败不得擅自删除问题投料、补入物料或替换配方版本。
90					got, readErr := os.ReadFile(filepath.Join(dir, stateFileName))
91					if readErr != nil {
92						t.Fatal(readErr)
93					}
94					if !bytes.Equal(got, original) {
95						t.Fatalf("拒绝打开不应改动台账文件")
96					}
97				})
98			}
99		}
100	}
101	
102	// 唯一合法的修复方向是让物料进入批次真正绑定的版本：同编号另一版本
103	// 或另一配方里存在该物料不算数；手工把物料补入绑定版本 R1/v1 后，
104	// 原投料（含序号、克数、登记人）完整保留，数量核对按补入后的版本计算。
105	func TestOpenMembershipFailureRecoveredOnlyViaBoundVersion(t *testing.T) {
106		dir := t.TempDir()
107		// M2 只出现在 R1/v2：第一次打开必须拒绝，且文件不被自动修复。
108		original := writeMembershipFeedingState(t, dir, "M2", StatusExecuting)
109		if s, err := Open(dir); !errors.Is(err, ErrCorruptData) {
110			if s != nil {
111				s.Close()
112			}
113			t.Fatalf("M2 只在 R1/v2 时应拒绝，得到 %v", err)
114		}
115		got, err := os.ReadFile(filepath.Join(dir, stateFileName))
116		if err != nil {
117			t.Fatal(err)
118		}
119		if !bytes.Equal(got, original) {
120			t.Fatalf("拒绝打开不应改动台账文件")
121		}
122	
123		// 手工把 M2 补入批次真正绑定的 R1/v1（R1/v2 保持不变），重新打开应成功。
124		var repaired persistedState
125		if err := json.Unmarshal(original, &repaired); err != nil {
126			t.Fatal(err)
127		}
128		for _, r := range repaired.Recipes {
129			if r.RecipeNo == "R1" && r.Version == "v1" {
130				r.Materials = append(r.Materials, materialRecord{MaterialNo: "M2", GramsMilli: 25000})
131			}
132		}
133		writeStateFile(t, dir, &repaired)
134	
135		s, err := Open(dir)
136		if err != nil {
137			t.Fatalf("物料进入绑定版本后应能打开: %v", err)
138		}
139		defer s.Close()
140		view, err := s.GetBatch("B-bad")
141		if err != nil {
142			t.Fatal(err)
143		}
144		if view.RecipeNo != "R1" || view.RecipeVersion != "v1" || view.PlannedPortions != 2 {
145			t.Fatalf("批次绑定信息应保持不变: %+v", view)
146		}
147		if len(view.Feedings) != 2 || view.Feedings[1].Seq != 2 ||
148			view.Feedings[1].MaterialNo != "M2" || view.Feedings[1].Grams != "50" {
149			t.Fatalf("原有两条投料应完整保留: %+v", view.Feedings)
150		}
151		mats := materialsMap(view)
152		if len(mats) != 2 {
153			t.Fatalf("应按补入后的 R1/v1 列出两种物料，得到 %d 项", len(mats))
154		}
155		// M1：100 × 2 = 200，实投 100；M2：25 × 2 = 50，实投 50（原问题投料）。
156		checkRequirement(t, mats, "M1", "200", "100", "-100")
157		checkRequirement(t, mats, "M2", "50", "50", "0")
158	}
159	
160	// 台账正常打开后，保存内容中的投料物料变成不属于绑定版本：下一次查询
161	// 批次或追加投料必须返回 ErrCorruptData，不能沿用此前读到的内容；
162	// 台账中另有完整批次时，查询、追加、关闭那个批次同样不能绕过问题；
163	// 被拒绝的查询不返回部分核对结果，被拒绝的写入不留业务变化、不占用
164	// 请求编号，原台账内容保持不变；恢复后原有记录与请求行为完整可用。
165	func TestMembershipCorruptionAfterOpenDetectedOnNextAccess(t *testing.T) {
166		cases := []struct {
167			name string
168			mat  string
169		}{
170			{"物料完全不存在", "M9"},
171			{"物料只在 R1/v2", "M2"},
172			{"物料只在另一配方", "M3"},
173		}
174		for _, tc := range cases {
175			t.Run(tc.name, func(t *testing.T) {
176				dir := t.TempDir()
177				s, err := Open(dir)
178				if err != nil {
179					t.Fatal(err)
180				}
181				defer s.Close()
182	
183				if _, err := s.RegisterRecipe("r1-v1", "R1", "v1", "配方一", []MaterialInput{
184					{MaterialNo: "M1", Grams: "100"},
185				}); err != nil {
186					t.Fatal(err)
187				}
188				if _, err := s.RegisterRecipe("r1-v2", "R1", "v2", "配方一改版", []MaterialInput{
189					{MaterialNo: "M2", Grams: "200"},
190				}); err != nil {
191					t.Fatal(err)
192				}
193				if _, err := s.RegisterRecipe("r2-v1", "R2", "v1", "配方二", []MaterialInput{
194					{MaterialNo: "M3", Grams: "300"},
195				}); err != nil {
196					t.Fatal(err)
197				}
198				// B1：随后被改坏的批次；B2：始终完整的批次（同绑 R1/v1）。
199				if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 10); err != nil {
200					t.Fatal(err)
201				}
202				if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 5); err != nil {
203					t.Fatal(err)
204				}
205				if _, err := s.StartBatch("s1", "B1"); err != nil {
206					t.Fatal(err)
207				}
208				if _, err := s.StartBatch("s2", "B2"); err != nil {
209					t.Fatal(err)
210				}
211				fixedTime := time.Date(2026, 9, 1, 9, 0, 0, 0, time.UTC)
212				if _, err := s.AddFeeding("f-b1", "B1", "M1", "100", fixedTime, "张三"); err != nil {
213					t.Fatal(err)
214				}
215				if _, err := s.AddFeeding("f-b2", "B2", "M1", "5", fixedTime, "李四"); err != nil {
216					t.Fatal(err)
217				}
218	
219				good, err := os.ReadFile(filepath.Join(dir, stateFileName))
220				if err != nil {
221					t.Fatal(err)
222				}
223				var broken persistedState
224				if err := json.Unmarshal(good, &broken); err != nil {
225					t.Fatal(err)
226				}
227				for _, b := range broken.Batches {
228					if b.BatchNo == "B1" {
229						// 50 克、正数、累计不超限；唯一问题是物料不属于 R1/v1。
230						b.Feedings = append(b.Feedings, feedingRecord{
231							Seq: 2, MaterialNo: tc.mat, GramsMilli: 50000,
232							Time: fixedTime, Registrar: "王五",
233						})
234					}
235				}
236				badBytes := writeStateFile(t, dir, &broken)
237	
238				// 查询损坏批次：失败且不返回部分核对结果。
239				if v, err := s.GetBatch("B1"); !errors.Is(err, ErrCorruptData) {
240					t.Fatalf("改坏后查询 B1 应返回 ErrCorruptData，得到 %v", err)
241				} else if v != nil {
242					t.Fatalf("被拒绝的查询不应返回部分台账视图: %+v", v)
243				}
244				// 查询完整批次同样不能绕过，也不能返回部分结果。
245				if v, err := s.GetBatch("B2"); !errors.Is(err, ErrCorruptData) {
246					t.Fatalf("查询完整批次 B2 也应失败，得到 %v", err)
247				} else if v != nil {
248					t.Fatalf("整份台账损坏时不应返回 B2 的部分视图: %+v", v)
249				}
250				// 配方查询同样重载整份台账，不能继续使用此前读到的内容。
251				if _, err := s.GetRecipe("R1", "v1"); !errors.Is(err, ErrCorruptData) {
252					t.Fatalf("改坏后查询配方也应返回 ErrCorruptData，得到 %v", err)
253				}
254				// 对完整批次追加投料、关闭批次都不能绕过读取检查。
255				if _, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "赵六"); !errors.Is(err, ErrCorruptData) {
256					t.Fatalf("损坏台账上对完整批次投料应返回 ErrCorruptData，得到 %v", err)
257				}
258				if _, err := s.AddFeeding("feed-bad-batch", "B1", "M1", "1", time.Now(), "赵六"); !errors.Is(err, ErrCorruptData) {
259					t.Fatalf("损坏台账上对损坏批次投料应返回 ErrCorruptData，得到 %v", err)
260				}
261				if _, err := s.CloseBatch("close-rejected", "B2"); !errors.Is(err, ErrCorruptData) {
262					t.Fatalf("损坏台账上关闭完整批次也应返回 ErrCorruptData，得到 %v", err)
263				}
264	
265				// 被拒绝的写入不留业务变化：文件内容不变，请求编号未被占用。
266				after, err := os.ReadFile(filepath.Join(dir, stateFileName))
267				if err != nil {
268					t.Fatal(err)
269				}
270				if !bytes.Equal(after, badBytes) {
271					t.Fatalf("被拒绝的写入不应改动台账文件")
272				}
273				for _, marker := range []string{"feed-rejected", "feed-bad-batch", "close-rejected"} {
274					if bytes.Contains(after, []byte(marker)) {
275						t.Fatalf("被拒绝的写入不应留下请求记录 %q", marker)
276					}
277				}
278	
279				// 恢复原内容后：问题投料从未被系统接受，两条合法投料完整，
280				// 完整批次状态不变（关闭被拒绝），原成功请求仍可幂等重放，
281				// 被拒绝过的请求编号可以正常使用并取得连续序号。
282				if err := os.WriteFile(filepath.Join(dir, stateFileName), good, 0o644); err != nil {
283					t.Fatal(err)
284				}
285				b1, err := s.GetBatch("B1")
286				if err != nil {
287					t.Fatalf("恢复后查询 B1 应成功: %v", err)
288				}
289				if len(b1.Feedings) != 1 || b1.Feedings[0].MaterialNo != "M1" || b1.Feedings[0].Grams != "100" {
290					t.Fatalf("B1 应只保留原合法投料: %+v", b1.Feedings)
291				}
292				b2, err := s.GetBatch("B2")
293				if err != nil {
294					t.Fatalf("恢复后查询 B2 应成功: %v", err)
295				}
296				if b2.Status != StatusExecuting {
297					t.Fatalf("被拒绝的关闭不应改变 B2 状态，得到 %s", b2.Status)
298				}
299				if len(b2.Feedings) != 1 || b2.Feedings[0].Grams != "5" {
300					t.Fatalf("B2 原有投料应保留: %+v", b2.Feedings)
301				}
302				replay, err := s.AddFeeding("f-b2", "B2", "M1", "5", fixedTime, "李四")
303				if err != nil {
304					t.Fatalf("恢复后重放原成功请求失败: %v", err)
305				}
306				if replay.Seq != 1 {
307					t.Fatalf("重放应返回第一次成功的结果，得到 seq=%d", replay.Seq)
308				}
309				f, err := s.AddFeeding("feed-rejected", "B2", "M1", "1", time.Now(), "赵六")
310				if err != nil {
311					t.Fatalf("被拒绝过的请求编号应仍可合法提交: %v", err)
312				}
313				if f.Seq != 2 || f.Grams != "1" {
314					t.Fatalf("新投料结果不正确: %+v", f)
315				}
316			})
317		}
318	}
319	
320	// 合法情形保留：同一物料可以出现在多个配方版本中，只要存在于批次真正
321	// 绑定的版本就能正常读取；各版本每份用量不同时，应投量按绑定版本与
322	// 计划份数计算，累计实投与差额按该物料的实际记录计算。实投不足或超过
323	// 应投量只是数量核对结果，不能被归属检查误判为损坏；没有投料的配方
324	// 物料仍显示零实投。已关闭批次的合法投料在重新打开后同样完整可读。
325	func TestSameMaterialAcrossVersionsKeepsReconciliationBehavior(t *testing.T) {
326		dir := t.TempDir()
327		s1, err := Open(dir)
328		if err != nil {
329			t.Fatal(err)
330		}
331		// M1 同时存在于两个版本且每份用量不同（100 vs 250）；
332		// M2、M0 只在 v1，M3 只在 v2。
333		if _, err := s1.RegisterRecipe("r1-v1", "R1", "v1", "配方初版", []MaterialInput{
334			{MaterialNo: "M1", Grams: "100"},
335			{MaterialNo: "M2", Grams: "0.5"},
336			{MaterialNo: "M0", Grams: "10"},
337		}); err != nil {
338			t.Fatal(err)
339		}
340		if _, err := s1.RegisterRecipe("r1-v2", "R1", "v2", "配方改版", []MaterialInput{
341			{MaterialNo: "M1", Grams: "250"},
342			{MaterialNo: "M3", Grams: "2"},
343		}); err != nil {
344			t.Fatal(err)
345		}
346	
347		// B1 绑定 v1、3 份：M1 实投 100（应投 300，欠投），M2、M0 不投料。
348		if _, err := s1.CreateBatch("b1", "B1", "R1", "v1", 3); err != nil {
349			t.Fatal(err)
350		}
351		if _, err := s1.StartBatch("s1", "B1"); err != nil {
352			t.Fatal(err)
353		}
354		if _, err := s1.AddFeeding("f-b1", "B1", "M1", "100", time.Now(), "张三"); err != nil {
355			t.Fatal(err)
356		}
357		// B2 绑定 v2、2 份：M1 实投 600（应投 500，超投），M3 不投料。
358		if _, err := s1.CreateBatch("b2", "B2", "R1", "v2", 2); err != nil {
359			t.Fatal(err)
360		}
361		if _, err := s1.StartBatch("s2", "B2"); err != nil {
362			t.Fatal(err)
363		}
364		if _, err := s1.AddFeeding("f-b2", "B2", "M1", "600", time.Now(), "李四"); err != nil {
365			t.Fatal(err)
366		}
367		if _, err := s1.CloseBatch("c1", "B1"); err != nil {
368			t.Fatal(err)
369		}
370	
371		// 写入侧归属仍然只认批次绑定的版本：只在 v1 的物料不能投给 v2 批次，
372		// 完全不存在的物料也一样。
373		for _, tc := range []struct{ reqNo, mat string }{
374			{"bad-m2", "M2"}, // 只在 v1
375			{"bad-m0", "M0"}, // 只在 v1
376			{"bad-m9", "M9"}, // 台账中不存在
377		} {
378			if _, err := s1.AddFeeding(tc.reqNo, "B2", tc.mat, "1", time.Now(), "王五"); !errors.Is(err, ErrMaterialNotInRecipe) {
379				t.Fatalf("向 v2 批次投绑定版本之外的物料 %q 应返回 ErrMaterialNotInRecipe，得到 %v",
380					tc.mat, err)
381			}
382		}
383		// 失败不占用请求编号：同一编号改投绑定版本内的 M1 应成功，序号连续。
384		f, err := s1.AddFeeding("bad-m2", "B2", "M1", "1", time.Now(), "王五")
385		if err != nil {
386			t.Fatalf("被拒绝的请求编号修正后应可使用: %v", err)
387		}
388		if f.Seq != 2 || f.Grams != "1" {
389			t.Fatalf("修正后投料结果不正确: %+v", f)
390		}
391	
392		// 关闭并重新打开：欠投/超投/零投料都不构成台账损坏，核对结果逐版本保留。
393		if err := s1.Close(); err != nil {
394			t.Fatal(err)
395		}
396		s2, err := Open(dir)
397		if err != nil {
398			t.Fatalf("含欠投与超投记录的合法台账应能重新打开: %v", err)
399		}
400		defer s2.Close()
401	
402		v1, err := s2.GetBatch("B1")
403		if err != nil {
404			t.Fatalf("重新打开后查询已关闭批次失败: %v", err)
405		}
406		if v1.Status != StatusClosed || v1.RecipeVersion != "v1" {
407			t.Fatalf("B1 状态与绑定版本应保留: %+v", v1)
408		}
409		m1 := materialsMap(v1)
410		if len(m1) != 3 {
411			t.Fatalf("B1 应只列 v1 的三种物料（不含 v2 新增的 M3），得到 %d 项: %+v", len(m1), m1)
412		}
413		checkRequirement(t, m1, "M1", "300", "100", "-200") // 欠投只是核对结果
414		checkRequirement(t, m1, "M2", "1.5", "0", "-1.5")  // 零实投仍显示
415		checkRequirement(t, m1, "M0", "30", "0", "-30")
416		if _, ok := m1["M3"]; ok {
417			t.Fatalf("v2 才有的 M3 不应出现在 v1 批次的核对中")
418		}
419	
420		v2, err := s2.GetBatch("B2")
421		if err != nil {
422			t.Fatalf("重新打开后查询 B2 失败: %v", err)
423		}
424		if v2.Status != StatusExecuting || v2.RecipeVersion != "v2" {
425			t.Fatalf("B2 状态与绑定版本应保留: %+v", v2)
426		}
427		m2 := materialsMap(v2)
428		if len(m2) != 2 {
429			t.Fatalf("B2 应只列 v2 的两种物料（不含 v1 的 M2、M0），得到 %d 项: %+v", len(m2), m2)
430		}
431		// 应投按 v2 的 250 × 2 = 500；实投 600 + 1 = 601，全部按 M1 的实际记录累计。
432		checkRequirement(t, m2, "M1", "500", "601", "101")
433		checkRequirement(t, m2, "M3", "4", "0", "-4")
434	}
